def _operator_phone(csv_id: int) -> str:
    """Temporary phone: +99895000NNNN — 9 digits after +998 (matches validator).
    Admins replace with real numbers via /admin/users.
    """
    return f"+99895000{csv_id:04d}"


def _operator_full_name(op: dict[str, Any]) -> str:
    parts = [op.get("last_name"), op.get("first_name")]
    return " ".join(p for p in parts if p).strip()


