# ============================================================================
# Seeder logic
# ============================================================================

def _parse_dt(s: str | None) -> datetime | None:
    if not s:
        return None
    try:
        return datetime.fromisoformat(s.replace(" ", "T"))
    except ValueError:
        return None


async def _ensure_operator(session: AsyncSession, op: dict[str, Any]) -> User:
    phone = _operator_phone(op["csv_id"])
    res = await session.execute(select(User).where(User.phone == phone))
    user = res.scalar_one_or_none()
    if user:
        return user

    user = User(
        phone=phone,
        full_name=_operator_full_name(op),
        role=UserRole.OPERATOR,
        is_active=True,
        is_phone_verified=True,
        password_hash=hash_password(op["login"]),
    )
    session.add(user)
    await session.flush()
    logger.info("seed.operator.created", login=op["login"], phone=phone)
    return user


async def _ensure_pipeline(session: AsyncSession) -> LeadPipeline:
    res = await session.execute(select(LeadPipeline).where(LeadPipeline.name == PIPELINE_NAME))
    pl = res.scalar_one_or_none()
    if pl:
        return pl
    pl = LeadPipeline(name=PIPELINE_NAME, is_active=True, is_default=True)
    session.add(pl)
    await session.flush()
    logger.info("seed.pipeline.created", name=PIPELINE_NAME)
    return pl


async def _ensure_stages(
    session: AsyncSession, pipeline: LeadPipeline,
) -> dict[int, LeadStage]:
    """Returns mapping: csv_col_id -> LeadStage."""
    out: dict[int, LeadStage] = {}
    for spec in STAGES:
        res = await session.execute(
            select(LeadStage).where(
                LeadStage.pipeline_id == pipeline.id,
                LeadStage.name == spec["name"],
            )
        )
        st = res.scalar_one_or_none()
        if not st:
            st = LeadStage(
                pipeline_id=pipeline.id,
                name=spec["name"],
                order_index=spec["order_index"],
                color=spec["color"],
                is_terminal=False,
            )
            session.add(st)
            await session.flush()
            logger.info("seed.stage.created", name=spec["name"])
        out[spec["csv_col_id"]] = st
    return out


async def _ensure_sources(session: AsyncSession) -> dict[str, LeadSource]:
    out: dict[str, LeadSource] = {}
    for spec in SOURCES:
        res = await session.execute(select(LeadSource).where(LeadSource.code == spec["code"]))
        src = res.scalar_one_or_none()
        if not src:
            src = LeadSource(code=spec["code"], name=spec["name"], is_active=True)
            session.add(src)
            await session.flush()
        out[spec["code"]] = src
    return out


async def _ensure_lost_reasons(session: AsyncSession) -> dict[str, LeadLostReason]:
    out: dict[str, LeadLostReason] = {}
    for spec in LOST_REASONS:
        res = await session.execute(
            select(LeadLostReason).where(LeadLostReason.name == spec["name"])
        )
        lr = res.scalar_one_or_none()
        if not lr:
            lr = LeadLostReason(name=spec["name"], is_active=True)
            session.add(lr)
            await session.flush()
        out[spec["code"]] = lr
    return out


async def _ensure_leads(
    session: AsyncSession,
    pipeline: LeadPipeline,
    stages: dict[int, LeadStage],
    sources: dict[str, LeadSource],
    lost_reasons: dict[str, LeadLostReason],
    operators: dict[int, User],
) -> dict[str, int]:
    stats = {"created": 0, "skipped_existing": 0, "skipped_no_stage": 0}

    fallback_stage = stages.get(LOST_BUCKET_FALLBACK_STAGE) or next(iter(stages.values()))

    for row in LEADS_DATA:
        col_id, owner_csv_id, full_name, phone, src_code, lr_code, lost_at, created_at, note = row

        # De-dup by phone
        res = await session.execute(select(Lead.id).where(Lead.phone == phone))
        if res.scalar_one_or_none() is not None:
            stats["skipped_existing"] += 1
            continue

        if col_id == LOST_BUCKET_COL_ID:
            stage = fallback_stage
            status = LeadStatus.LOST
        else:
            stage = stages.get(col_id) or fallback_stage
            status = LeadStatus.OPEN

        if lr_code:
            status = LeadStatus.LOST

        assigned = operators.get(owner_csv_id) if owner_csv_id is not None else None

        lead = Lead(
            full_name=full_name,
            phone=phone,
            pipeline_id=pipeline.id,
            stage_id=stage.id,
            source_id=sources.get(src_code).id if src_code else None,
            assigned_to_id=assigned.id if assigned else None,
            status=status,
            lost_reason_id=lost_reasons.get(lr_code).id if lr_code else None,
            lost_at=_parse_dt(lost_at) if lr_code else None,
            stage_entered_at=_parse_dt(created_at) or datetime.utcnow(),
            notes=note,
        )
        session.add(lead)
        stats["created"] += 1

        # Flush every 100 to keep memory bounded
        if stats["created"] % 100 == 0:
            await session.flush()

    await session.flush()
    return stats


async def main() -> None:
    configure_logging(debug=False)
    async with async_session_factory() as session:
        async with session.begin():
            # 1. Operators
            ops_by_csv: dict[int, User] = {}
            for op in OPERATORS:
                user = await _ensure_operator(session, op)
                ops_by_csv[op["csv_id"]] = user

            # 2. Pipeline + stages
            pipeline = await _ensure_pipeline(session)
            stages = await _ensure_stages(session, pipeline)

            # 3. Sources + lost reasons
            sources = await _ensure_sources(session)
            lost_reasons = await _ensure_lost_reasons(session)

            # 4. Leads
            stats = await _ensure_leads(
                session, pipeline, stages, sources, lost_reasons, ops_by_csv,
            )
            logger.info(
                "seed.leads.done",
                created=stats["created"],
                skipped_existing=stats["skipped_existing"],
            )

    print("\n=== Seed summary ===")
    print(f"  operators:        {len(OPERATORS)}")
    print(f"  pipeline:         {PIPELINE_NAME}")
    print(f"  stages:           {len(STAGES)}")
    print(f"  sources:          {len(SOURCES)}")
    print(f"  lost reasons:     {len(LOST_REASONS)}")
    print(f"  leads created:    {stats['created']}")
    print(f"  leads skipped:    {stats['skipped_existing']} (already existed by phone)")


if __name__ == "__main__":
    asyncio.run(main())
